const workflow = $input.first().json;
if (workflow.id !== 'Domz943gXmQLejtF' || !Array.isArray(workflow.nodes)) throw new Error('Expected staging Interaction Handler definition');
const nodes = Object.fromEntries(workflow.nodes.map(n => [n.name,n]));
const results = [];
const fixture = {test_mode:true,liveMode:false,session_key:'test-only',channel_id:'TEST',thread_ts:'1.000001',message_ts:'1.000002',requested_count:10,slack_user_email:'researcher@example.com'};
function context(extra={}) {
 return {'Parse Payload':fixture,'Load Session':fixture,'Load Config (Approve)':{liveMode:false,emailSubject:'Research',emailBody:'Book: {{calendly_link}}'},...extra};
}
function run(name, ctx, input={}) {
 const dollar = n => {
  if (!(n in ctx)) throw new Error('Unexecuted node: '+n);
  const data=Array.isArray(ctx[n])?ctx[n]:[ctx[n]];
  return {first:()=>({json:data[0]}),all:()=>data.map(json=>({json}))};
 };
 const values=Array.isArray(input)?input:[input];
 return new Function('$','$input',nodes[name].parameters.jsCode)(dollar,{first:()=>({json:values[0]}),all:()=>values.map(json=>({json}))});
}
function check(name, fn) {
 const checks=[];
 const assert=(label,ok)=>checks.push({name:label,status:ok?'PASS':'FAIL'});
 try { fn(assert); } catch(e) {assert('No exception: '+e.message,false);}
 results.push({name,checks,status:checks.every(c=>c.status==='PASS')?'PASS':'FAIL'});
}
function guard(name, ctx, input={}) {
 const expression=nodes[name].parameters.conditions.conditions[0].leftValue.trim().slice(3,-2);
 return new Function('$','$json','return ('+expression+')')(n=>({first:()=>({json:ctx[n]})}),input);
}
const section = text => ({type:'section',block_id:'old',expand:true,text:{type:'mrkdwn',text}});
for(const length of [2999,3000,3001,3105,3309,7000]) {
 check('Slack section '+length, assert=>{
  const original='a'.repeat(length);
  const p={...fixture,action_id:'uxr_sample_redraw',full_payload:{message:{blocks:[section(original),{type:'actions',elements:[]}]}}};
  const out=run('Freeze Clicked Message',context({'Parse Payload':p}))[0].json;
  const parts=out.frozenBlocks.filter(b=>b.type==='section');
  assert('All sections <=3000',parts.every(b=>b.text.text.length<=3000));
  assert('Full text preserved',parts.map(b=>b.text.text).join('')===original);
  assert('Action stays frozen',out.shouldFreeze&&!out.frozenBlocks.some(b=>b.type==='actions'));
  assert('Redraw loader present',JSON.stringify(out.frozenBlocks).includes('Drawing a new sample'));
 });
}
check('200 candidates with expanded mailto links', assert=>{
 const original=Array.from({length:200},(_,i)=>(i+1)+'. <mailto:person'+i+'@example.com|person'+i+'@example.com> · <https://fly.customer.io/people/'+i+'|CIO>').join('\n');
 const p={...fixture,action_id:'uxr_approve_list_yes',full_payload:{message:{blocks:[section(original)]}}};
 const out=run('Freeze Clicked Message',context({'Parse Payload':p}))[0].json;
 assert('50-block limit',out.frozenBlocks.length<=50);
 assert('Section limit',out.frozenBlocks.every(b=>!b.text||b.text.text.length<=3000));
 assert('All candidates and links preserved',out.frozenBlocks.filter(b=>b.type==='section').map(b=>b.text.text).join('')===original);
 assert('Links not split',out.frozenBlocks.filter(b=>b.type==='section').every(b=>(b.text.text.match(/</g)||[]).length===(b.text.text.match(/>/g)||[]).length));
});
check('Completed redraw removes loader',assert=>{
 const frozen={...fixture,action_id:'uxr_sample_redraw',shouldFreeze:true,frozenBlocks:[section('Candidates'),{type:'context',elements:[{type:'mrkdwn',text:':loading: Drawing a new sample…'}]}]};
 const out=run('Clear Sample Loading',context({'Freeze Clicked Message':frozen}),{ok:true})[0].json;
 assert('List retained',out.frozenBlocks[0].text.text==='Candidates');
 assert('Loader removed',!JSON.stringify(out.frozenBlocks).includes(':loading:'));
 assert('Failed post retains loader',run('Clear Sample Loading',context({'Freeze Clicked Message':frozen}),{ok:false}).length===0);
});
check('CSV redraw reuses full email pool',assert=>{
 const emails=Array.from({length:1101},(_,i)=>'p'+i+'@example.com');
 const row={...fixture,audience:'csv',requested_count:50,csv_emails_json:JSON.stringify(emails)};
 const out=run('Prepare Search',context({'Load Session':row,'Parse Payload':{...fixture,action_id:'uxr_sample_redraw'}}))[0].json;
 assert('All uploaded emails retained',out.filters.emails.length===1101);
 assert('Requested size preserved',out.sampleSize===50);
 assert('No new CSV download',out.csv_download===false);
});
const member={statusCode:200,body:{collection:[{user:{uri:'https://api.calendly.com/users/test-user'}}]}};
const events={statusCode:200,body:{collection:[{active:true,scheduling_url:'https://calendly.com/test/research',name:'Research',duration:30}]}};
const scenarios=[
 ['Missing Slack email',{...fixture,slack_user_email:''},null,null,'missing_email'],
 ['Invalid Slack email',{...fixture,slack_user_email:'invalid'},null,null,'missing_email'],
 ['Membership 400',fixture,{statusCode:400,body:{}},null,'membership_error'],
 ['Membership 401',fixture,{statusCode:401,body:{}},null,'membership_error'],
 ['Membership 403',fixture,{statusCode:403,body:{}},null,'membership_error'],
 ['No account',fixture,{statusCode:200,body:{collection:[]}},null,'no_account'],
 ['Events 404',fixture,member,{statusCode:404,body:{}},'events_error'],
 ['Events network error',fixture,member,{error:'timeout'},'events_error'],
 ['No active events',fixture,member,{statusCode:200,body:{collection:[]}},'no_events'],
 ['Successful events',fixture,member,events,'ready']
];
for(const [name,row,m,e,status] of scenarios)check(name,assert=>{
 const ctx=context({'Load Session':row});
 if(m)ctx['Calendly Membership']=m;if(e)ctx['Calendly Event Types']=e;
 const out=run('Build Email Preview',ctx)[0].json;
 const blocks=JSON.parse(out.blocks);
 assert('Correct diagnostic',out.calendly_status===status);
 assert('Explicit TEST MODE label',JSON.stringify(blocks).includes('Approve & Send (TEST MODE)'));
 assert('Options only on success',JSON.parse(out.sess.calendly_options_json).length===(status==='ready'?1:0));
 assert('Email guard',guard('Has Slack Email?',ctx)===(status!=='missing_email'));
 if(m)assert('Membership guard',guard('Calendly Member Found?',ctx,m)===(m===member));
 assert('No misleading no-events label',!JSON.stringify(blocks).includes('no Calendly events found for your Slack email'));
});
check('Calendly failure branches bypass HTTP',assert=>{
 const edges=(name,index)=>((workflow.connections[name]||{}).main||[])[index]||[];
 assert('Missing email -> preview',edges('Has Slack Email?',1).some(e=>e.node==='Build Email Preview'));
 assert('Invalid membership -> preview',edges('Calendly Member Found?',1).some(e=>e.node==='Build Email Preview'));
 assert('Config enters email guard',edges('Load Config (Approve)',0).some(e=>e.node==='Has Slack Email?'));
 assert('No fake email',!nodes['Calendly Membership'].parameters.url.includes('nobody@invalid'));
 assert('No fake user',!nodes['Calendly Event Types'].parameters.url.includes('users/none'));
});

for (const audience of ['n8n_users','volunteers','csv']) check('Repeated redraw preserves target: '+audience, assert=>{
 let row={...fixture,audience,requested_count:0,filters_json:'{}',csv_emails_json:'["a@example.com"]'};
 for(const [idx,size] of [20,16,12,5,2,0,35].entries()){
  const p=idx===0
    ? (audience==='csv'
      ? {...fixture,action_id:'uxr_sample_csv_submit',action_value:{values:{csv_block:{uxr_csv_file:{files:[{url_private:'https://files.slack.com/test.csv'}]}},csv_count_block:{uxr_csv_count:{value:'35'}}}}}
      : {...fixture,action_id:'uxr_sample_draw',full_payload:{state:{values:{sample_size_block:{uxr_sample_size_input:{value:'35'}}}}}})
    : {...fixture,action_id:'uxr_sample_redraw',full_payload:{}};
  const ctx=context({'Parse Payload':p,'Load Session':row});
  const prep=run('Prepare Search',ctx)[0].json;
  assert('Draw '+idx+' requests 35',prep.sampleSize===35);
  const candidates=Array.from({length:size},(_,i)=>({email:'p'+i+'@example.com',cio_id:'test'+i}));
  const built=run('Build Candidates',context({'Prepare Search':prep}),{candidates,requestedSize:35})[0].json;
  assert('Draw '+idx+' stores target 35',built.sess.sample_target_count===35);
  assert('Draw '+idx+' stores actual count',built.sess.requested_count===size);
  assert('Shortfall copy does not claim pool exhausted',!built.blocks.includes('The pool for these filters is small'));
  row={...row,...built.sess};
 }
 const preview=run('Build Email Preview',context({'Load Session':{...row,requested_count:2},'Calendly Membership':member,'Calendly Event Types':events}))[0].json;
 assert('Preview uses actual count',preview.blocks.includes('*2 people*'));
});
check('CSV everyone mode survives shortfalls',assert=>{
 const row={...fixture,audience:'csv',sample_target_count:0,requested_count:2,csv_emails_json:'["a@example.com"]'};
 const prep=run('Prepare Search',context({'Load Session':row,'Parse Payload':{...fixture,action_id:'uxr_sample_redraw'}}))[0].json;
 assert('Zero means everyone',prep.sampleSize===0);
 const built=run('Build Candidates',context({'Prepare Search':prep}),{candidates:[{email:'a@example.com'}],requestedSize:200})[0].json;
 assert('Zero target persists',built.sess.sample_target_count===0);
 assert('Selected count is one',built.sess.requested_count===1);
});
check('Search failure preserves target',assert=>{
 const prep={session_key:'test',mode:'n8n_users',sampleSize:35,filters:{}};
 const built=run('Build Candidates',context({'Prepare Search':prep}),{error:'synthetic API failure'})[0].json;
 assert('Target retained',built.sess.sample_target_count===35);
 assert('No candidates reported',built.sess.requested_count===0);
});
check('Legacy session fallback',assert=>{
 for(const target of [undefined,null]){
  const row={...fixture,audience:'n8n_users',requested_count:16,sample_target_count:target};
  const out=run('Prepare Search',context({'Load Session':row}))[0].json;
  assert('Uses known legacy count',out.sampleSize===16);
 }
});
check('Manual removals leave target intact',assert=>{
 const columns=nodes['Save Edited Candidate Count'].parameters.columns.value;
 assert('Removal does not overwrite target',!Object.prototype.hasOwnProperty.call(columns,'sample_target_count'));
 const out=run('Prepare Search',context({'Load Session':{...fixture,audience:'n8n_users',requested_count:2,sample_target_count:35}}))[0].json;
 assert('Redraw still requests original target',out.sampleSize===35);
});
check('Persistence and reset mappings',assert=>{
 assert('Persists new target',String(nodes['Save Session (Candidates)'].parameters.columns.value.sample_target_count).includes('$json.sess.sample_target_count'));
 for(const name of ['Save Session (Audience)','Save Session (CSV)'])assert(name+' resets target',nodes[name].parameters.columns.value.sample_target_count===null);
});

return [{json:{suite:'UXR Handler regression',test_mode:true,sourceWorkflowId:workflow.id,sourceVersionId:workflow.versionId,coverage:'Current Code node logic and routing assertions with simulated inputs; no Slack delivery or full handler execution',results,status:results.every(r=>r.status==='PASS')?'PASS':'FAIL'}}];
